"""Marketing kit and cover concepts, generated by the LLM as background jobs."""

from __future__ import annotations

import json
import re

from sqlmodel import Session, select

from .. import events, llm
from ..db import session_scope
from ..models import CodexEntry, Project
from ..models.publish_extra import MarketingAsset
from .compile import chapter_texts
from .releases import get_metadata

KINDS = {
    "blurb": "Write back-cover copy (150 to 200 words): a hook line, the protagonist's want and the stakes, "
             "end on a question or turn. No spoilers past the midpoint.",
    "taglines": "Write 8 distinct taglines, each under 12 words, one per line, no numbering.",
    "query_letter": "Write a literary agent query letter (250 to 300 words): personalisation placeholder, "
                    "hook, story paragraph, comps and word count, short bio placeholder.",
    "synopsis_1p": "Write a one-page synopsis (about 500 words) in present tense, third person, "
                   "covering the whole arc including the ending.",
    "newsletter": "Write a launch newsletter email for readers: subject line, preview text, then a warm "
                  "200-word body with a single call to action.",
    "a_plus_copy": "Write Amazon A+ Content copy: 3 modules, each with a heading (under 8 words) and "
                   "40 to 60 words of body copy. Label them Module 1, 2, 3.",
}

SYSTEM = ("You are a book marketing copywriter for a novelist. Write in plain, vivid English. "
          "Never invent facts that contradict the material. Output only the requested copy.")


def book_context(session: Session, project: Project, excerpt_words: int = 900) -> str:
    meta = get_metadata(session, project.id)
    codex = session.exec(
        select(CodexEntry).where(CodexEntry.project_id == project.id)
        .order_by(CodexEntry.kind, CodexEntry.name).limit(24)
    ).all()
    lines = [f"Title: {project.title}", f"Author: {project.author or 'the author'}",
             f"Genre: {project.genre or 'fiction'}"]
    if meta.subtitle:
        lines.append(f"Subtitle: {meta.subtitle}")
    if meta.series:
        lines.append(f"Series: {meta.series} #{meta.series_number or 1}")
    if project.premise:
        lines.append(f"Premise: {project.premise}")
    if meta.description:
        lines.append(f"Current description: {meta.description}")
    if meta.comps:
        lines.append("Comparable titles: " + "; ".join(str(c) for c in meta.comps))
    bible = project.bible or {}
    for k in ("tone", "themes", "setting"):
        if bible.get(k):
            lines.append(f"{k.title()}: {bible[k]}")
    if codex:
        lines.append("Codex:")
        for e in codex:
            lines.append(f"- {e.name} ({e.kind}{', ' + e.role if e.role else ''}): {e.summary[:200]}")
    words = " ".join(c["text"] for c in chapter_texts(session, project.id) if c["text"]).split()
    if words:
        lines.append("Opening excerpt: " + " ".join(words[:excerpt_words]))
    return "\n".join(lines)


def generate_marketing(project_id: str, kinds: list[str]):
    def fn(run_id: str) -> dict:
        made = []
        for kind in kinds:
            with session_scope() as s:
                project = s.get(Project, project_id)
                ctx = book_context(s, project)
                text, _route, model = llm.complete(s, SYSTEM, f"{ctx}\n\nTask: {KINDS[kind]}")
                a = MarketingAsset(project_id=project_id, kind=kind, content=text.strip(), model=model or "")
                s.add(a)
                s.flush()
                made.append(a.id)
            events.publish(project_id, "publish.updated", {"marketing": kind})
        return {"assets": made, "kinds": kinds}
    return fn


CONCEPT_TASK = """Propose exactly 3 distinct cover concepts for this book.
Return JSON only: {"concepts": [{"name": str, "mood": str, "palette": ["#rrggbb", x4],
"composition": str, "typography": str, "image_prompt": str}]}.
image_prompt must be a ready-to-paste prompt for an image model: subject, setting, lighting,
style, lens or medium, aspect ratio 2:3 portrait, leave the top third calm for the title, no text."""


def parse_concepts(text: str) -> list[dict]:
    m = re.search(r"\{.*\}", text or "", re.S)
    data = {}
    if m:
        try:
            data = json.loads(m.group(0))
        except json.JSONDecodeError:
            data = {}
    raw = data.get("concepts") if isinstance(data, dict) else None
    out = []
    for c in (raw or [])[:3]:
        if not isinstance(c, dict):
            continue
        palette = [p for p in c.get("palette", []) if isinstance(p, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", p)]
        out.append({
            "name": str(c.get("name", "Concept"))[:80],
            "mood": str(c.get("mood", ""))[:200],
            "palette": palette[:6],
            "composition": str(c.get("composition", "")),
            "typography": str(c.get("typography", "")),
            "image_prompt": str(c.get("image_prompt", "")),
        })
    return out


def generate_concepts(project_id: str):
    def fn(run_id: str) -> dict:
        with session_scope() as s:
            project = s.get(Project, project_id)
            ctx = book_context(s, project, excerpt_words=400)
            text, _route, model = llm.complete(
                s, "You are an award-winning book cover art director.", f"{ctx}\n\n{CONCEPT_TASK}")
            concepts = parse_concepts(text)
            if not concepts:
                raise ValueError("The model did not return usable concepts. Try again.")
            s.add(MarketingAsset(project_id=project_id, kind="cover_concepts",
                                 content=json.dumps(concepts), model=model or ""))
        events.publish(project_id, "publish.updated", {"concepts": len(concepts)})
        return {"concepts": concepts}
    return fn


def latest_concepts(session: Session, project_id: str) -> list[dict]:
    a = session.exec(
        select(MarketingAsset).where(MarketingAsset.project_id == project_id,
                                     MarketingAsset.kind == "cover_concepts")
        .order_by(MarketingAsset.created_at.desc())
    ).first()
    if not a:
        return []
    try:
        return json.loads(a.content)
    except json.JSONDecodeError:
        return []
